SELECT p.gender, a.admittime, a.dischtime, a.los, i.imaging_status, e.ecg_status, pft.pft_status, COUNT(DISTINCT d.itemid) AS num_diagnostics FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN transfers t ON a.subject_id = t.subject_id JOIN labevents d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id JOIN icustays i ON a.subject_id = i.subject_id AND a.hadm_id = i.hadm_id JOIN emar e ON a.subject_id = e.subject_id AND a.hadm_id = e.hadm_id JOIN pftevents pft ON a.subject_id = pft.subject_id AND a.hadm_id = pft.hadm_id WHERE p.gender = 'F' AND p.anchor_age = 67 AND i.imaging_status = 'lower GI bleed' AND (a.los BETWEEN 1 AND 3 OR a.los BETWEEN 4 AND 7) AND (e.ecg_status = 'ECG' OR e.ecg_status = 'EEG' OR e.ecg_status = 'PFT') AND (d.itemid IN (SELECT itemid FROM d_labitems WHERE category = 'imaging') OR d.itemid IN (SELECT itemid FROM d_items WHERE category = 'ECG/EEG/PFT')) GROUP BY p.gender, a.admittime, a.dischtime, a.los, i.imaging_status, e.ecg_status, pft.pft_status ORDER BY p.gender, a.admittime, a.dischtime, a.los, i.imaging_status, e.ecg_status, pft.pft_status NULLS LAST;